return [
// Core, title, concrete action, measurable evidence, result type, target.
31 => ['Development','Pregledaj svoj prvi ciklus','Otvori svoje rezultate i izdvoji jednu naviku koja radi te jednu koju želiš popraviti. Usporedi razgovore i dogovorene nastavke, a ne samo klikove.','Zapisana je jedna uspješna navika, jedna prepreka i sljedeći korak.','planning',1],
32 => ['Retention','Provjeri iskustvo kupca','Javi se dvjema osobama koje su pristale na podršku. Pitaj je li im sve jasno oko korištenja prema deklaraciji i kakvu pomoć trebaju; zdravstvena pitanja uputi stručnjaku.','Zabilježena su dva javljanja i dogovoreni nastavci, bez zdravstvenih detalja.','customer_checkin',2],
33 => ['Productivity','Poveži potrebu i koristan sadržaj','Za jednu izraženu potrebu pronađi relevantan FCC članak, provjeri njegov sadržaj i podijeli vlastitu referral poveznicu uz jedno otvoreno pitanje.','Poslana je jedna osobna preporuka uz dopuštenje primatelja.','recommendation',1],
34 => ['Recruitment','Otvori razgovor o poslu','S dvjema osobama koje su pokazale interes razgovaraj o vremenu, motivaciji i očekivanjima. Pitaj žele li vidjeti kako posao izgleda; nemoj obećavati zaradu.','Zabilježena su dva razgovora i izbor osobe: nastavak, kasnije ili ne.','conversation',2],
35 => ['Development','Objasni četiri područja svojim riječima','Mentoru u dvije minute objasni Recruitment, Retention, Productivity i Development. Za svako navedi jednu svoju konkretnu radnju.','Mentor ili tvoja bilješka potvrđuje četiri primjera i jednu doradu.','coaching',1],
36 => ['Retention','Dogovori ritam podrške','S dvama kupcima provjeri žele li povremeno javljanje i koji im termin odgovara. Ako ne žele, ažuriraj dozvolu kontakta.','Ažurirana su dva dogovora o podršci.','customer_checkin',2],
37 => ['Productivity','Napravi jasnu preporuku','Na temelju stvarnog interesa napiši kratku preporuku: potreba, relevantna informacija, cijena na službenoj stranici i pitanje za nastavak. Koristi samo provjerene tvrdnje.','Pripremljena je jedna preporuka koju je mentor pregledao ili primatelj zatražio.','recommendation',1],
38 => ['Recruitment','Pozovi na poslovnu prezentaciju','Osobno pozovi dvije zainteresirane osobe na nedjeljni webinar u 19:00 Europe/Zagreb. Pitaj odgovara li im termin i ponudi poveznicu tek uz interes.','Evidentirana su dva osobna poziva i odgovori.','invitation',2],
39 => ['Retention','Zatvori otvorene dogovore','Pregledaj dospjela javljanja i nastavi dva ranija razgovora. Ponudi jasan izbor nastavka ili odgode, bez ponavljanog nagovaranja.','Dva razgovora imaju sljedeći datum ili su zaključena.','follow_up',2],
40 => ['Development','Provjeri deset koraka primjene','Usporedi korake 31–39: što je donijelo odgovor, što je ostalo bez odgovora i što si naučio/la. Izaberi jedan mali pokus za idući tjedan.','Zabilježen je pokus, očekivani signal i datum pregleda.','planning',1],
41 => ['Productivity','Pojednostavni glavnu karticu','Na mobitelu provjeri glavnu karticu: uvod, glavni poziv i kontakt. Ukloni jednu suvišnu uputu bez brisanja važnog sadržaja i provjeri svoj WhatsApp broj.','Javna kartica otvara se, kontakt vodi tebi i glavni korak je jasan.','content',1],
42 => ['Recruitment','Saznaj što je gost razumio','S dvama zainteresiranim gostima razgovaraj o njihovim pitanjima nakon prezentacije. Ako je nisu gledali, dogovorite hoće li i kada.','Dva gosta imaju zabilježeno pitanje i dogovoreni sljedeći korak.','follow_up',2],
43 => ['Retention','Podrži kupca nakon odabira','Provjeri s jednom osobom zna li pronaći službene upute, narudžbu i kontakt podrške. Ne savjetuj promjene terapije ni proizvode kao liječenje.','Osoba zna gdje pronaći upute i kome se javiti.','customer_checkin',1],
44 => ['Development','Pokaži jednostavan početak','Zainteresiranom novom suradniku ili mentoru pokaži prijavu, glavnu karticu, prvi zadatak i vlastitu poveznicu. Neka osoba sama ponovi jedan korak.','Osoba samostalno pronalazi karticu i svoj sljedeći zadatak.','onboarding',1],
45 => ['Productivity','Napiši koristan odgovor','Izaberi stvarno često pitanje i pripremi kratak odgovor s provjerenim FCC člankom. Jasno odvoji osobno iskustvo od potvrđene informacije.','Pripremljen je jedan jasan odgovor i provjeren izvor.','content',1],
46 => ['Recruitment','Razgovaraj o realnom tempu','S jednom zainteresiranom osobom prođi tjedno vrijeme, podršku i stvarne obveze. Reci da rezultat ovisi o radu i okolnostima, bez jamstva prihoda.','Osoba je odabrala realan tempo ili odlučila ne nastaviti.','conversation',1],
47 => ['Retention','Zatraži povratnu informaciju','Dvije osobe pitaj što im je u tvojoj podršci korisno, a što bi pojednostavnile. Za javno dijeljenje iskustva potrebna je zasebna dozvola.','Zabilježene su dvije povratne informacije i jedna prilagodba podrške.','customer_checkin',2],
48 => ['Development','Pomogni bez preuzimanja zadatka','Suradniku ili mentoru postavi tri pitanja: što želiš napraviti, gdje zapinješ i koji je najmanji sljedeći korak. Pusti osobu da sama odabere radnju.','Dogovoren je jedan samostalan korak i termin provjere.','coaching',1],
49 => ['Productivity','Uredi otvorene preporuke','Pregledaj dvije preporuke koje si već poslao/la. Provjeri relevantnost poveznice i pitaj postoji li pitanje, uz poštovanje dogovorenog termina.','Obje preporuke imaju jasan status i sljedeći korak.','follow_up',2],
50 => ['Development','Provjeri ravnotežu 4 Core','Za svako od četiri područja zapiši radnju iz zadnjih deset koraka. Odaberi područje koje zanemaruješ i rezerviraj mu jedan termin.','Pregled sadrži četiri primjera i jedan termin za slabije područje.','planning',1],
51 => ['Recruitment','Pripremi gosta za webinar','Jednoj zainteresiranoj osobi pojasni što će čuti na webinaru, trajanje i termin nedjeljom u 19:00. Pitaj što bi voljela saznati.','Gost ima poveznicu, termin i zapisano pitanje.','invitation',1],
52 => ['Retention','Provjeri dugoročnu podršku','S dvjema osobama provjeri je li dogovoreni ritam podrške i dalje koristan. Ne pretpostavljaj novu kupnju; prepusti im odluku.','Ažurirana su dva dogovora bez pritiska na narudžbu.','customer_checkin',2],
53 => ['Productivity','Izmjeri put od interesa do razgovora','Pogledaj FCC rezultate i svoje kontakte. Usporedi kvalificirane klikove, upite i dogovorene razgovore; klik nemoj označiti kao prodaju.','Zapisana su tri odvojena pokazatelja i jedna konkretna dorada.','planning',1],
54 => ['Development','Uvježbaj prigovor s mentorom','Odaberi jedno stvarno pitanje poput nemam vremena ili nisam siguran. Saslušaj, provjeri što osoba misli i ponudi informaciju bez pritiska.','Odradio/la si jednu vježbu i zapisao/la bolji odgovor.','coaching',1],
55 => ['Recruitment','Pomozi osobi donijeti vlastitu odluku','Nastavi jedan dogovoreni poslovni razgovor. Sažmi pitanja i ponudi nastavak, odgodu ili završetak; svaki odgovor prihvati.','Razgovor ima jasno zabilježenu odluku i eventualni datum.','follow_up',1],
56 => ['Retention','Uredi podatke o kontaktima','Pregledaj tri kontakta: aktualnost dogovora, dozvolu javljanja i rok. Ukloni nepotrebne privatne bilješke; ne mijenjaj status u kupca bez potvrde.','Tri zapisa sadrže samo potrebne i točne poslovne informacije.','planning',3],
57 => ['Productivity','Ponovi ono što je donijelo koristan odgovor','Odaberi jednu prethodnu radnju koja je otvorila kvalitetan razgovor i primijeni je u novom relevantnom razgovoru uz dopuštenje osobe.','Odradio/la si jednu ponovljivu radnju i zapisao/la što si naučio/la.','conversation',1],
58 => ['Development','Provjeri može li se korak ponoviti','S novim suradnikom ili mentorom ponovi put: kartica, korisna poveznica, razgovor i dogovoreni nastavak. Osoba vodi, ti pomažeš samo kada zatraži.','Jedan cijeli put obavljen je samostalno ili je prepoznata konkretna prepreka.','onboarding',1],
59 => ['Recruitment','Pripremi sljedeći tjedan','Odaberi dvije osobe sa stvarnim interesom i dogovori sljedeći razgovor ili prezentaciju. Za osobe koje ne žele nastavak zatvori dogovor.','Dva kontakta imaju jasno određen sljedeći korak ili zatvaranje.','follow_up',2],
60 => ['Development','Složi svoj održivi 4 Core ritam','Pregledaj svih 60 koraka i s mentorom složi sljedeći mjesec: jedan cilj, raspoloživo vrijeme, radnja za svaki Core i tjedni osvrt. Odvoji vlastite aktivnosti od službenih CC rezultata.','Spremljen je plan s četiri područja, jednim mjerljivim ciljem i terminom osvrta.','planning',1],
